def transform(grid):
    h, w = len(grid), len(grid[0])

    # A uniform row separates two grids to compare cell by cell.
    for r in range(h):
        if all(v == grid[r][0] for v in grid[r]):
            upper, lower = grid[:r], grid[r + 1:]
            n = min(len(upper), len(lower))
            return [
                [2 if upper[i][j] != 0 and lower[i][j] != 0 else 0
                 for j in range(w)]
                for i in range(n)
            ]

    # A uniform column separates two grids to compare cell by cell.
    for c in range(w):
        if all(grid[i][c] == grid[0][c] for i in range(h)):
            left_width = c
            right_width = w - c - 1
            n = min(left_width, right_width)
            return [
                [2 if grid[i][j] != 0 and grid[i][c + 1 + j] != 0 else 0
                 for j in range(n)]
                for i in range(h)
            ]

    return []
